from pathlib import Path
import json,sys,hashlib,datetime
import fitz
from PIL import Image
R=Path(__file__).resolve().parents[3];sys.path.insert(0,str(R/'scripts'));from validate import canonical_json,question_hash
snap=json.loads((R/'audits/question-visuals/stage-L20-L22.json').read_text());current=json.loads((R/'data/question-visuals/manifest.json').read_text());records={r['questionId']:r for r in current['records']};assets={a['id']:a for a in current['assets']};by={q['id']:q for q in json.loads((R/'data/bank.json').read_text())['questions']}
sha=lambda v:hashlib.sha256(canonical_json(v).encode()).hexdigest()
raw=R/'sources/raw/AI_for_Robotics_All_Lectures.pdf';sourcehash=hashlib.sha256(raw.read_bytes()).hexdigest();doc=fitz.open(raw)
exclude={'W05-L21-Q054':'p0661 lower comparator/sign crop is clipped; awaiting recrop.','W05-L22-Q044':'Missing p0687 simple gear-code comparator input; awaiting asset binding.','W05-L22-Q053':'p0689 b_eff_arr line clipped; awaiting recrop.'}
notes={661:'Both lower desired-minus-actual comparator signs and complete signal paths are now included after correction.',610:'All l1/l2/d1 schematic labels and arrows visible; no worked output.',614:'Complete DH input table including header, all four rows and first-row translation inputs.',615:'Four individual transform matrices intact; multiplied result excluded.',616:'Model x/y/z/yaw equations and coordinate convention intact, with numerical input values but no evaluated x/y or inverse-kinematics answer.',618:'Red inner and green outer workspace circles, radii labels and link geometry visible.',619:'Complete 4x4 Jacobian and task/joint ordering visible, with determinant solution excluded.',621:'Full mass-matrix structure, component formulas and COM assumptions visible; no numerical substitution answers.',631:'All first-page BOM line items, quantities, unit costs and categories visible; subtotal absent.',632:'All second-page BOM lines including repeated Safety PLC visible; computed total absent.',641:'Full open-loop reference arrows and torque path visible.',642:'Closed-loop measured position/velocity returns intact.',654:'Both measured feedback paths and negative summing signs visible.',659:'Full normalized-input mass scaling and actual-state additive compensation visible.',675:'Circuit components, current loop and opposing back-EMF polarity visible without solved circuit equation.',682:'Both lateral and torsional distributed-to-lumped models and their distinct mass/inertia factors visible.',684:'Entire forward chain and encoder feedback topology visible.',685:'Function parameter order, state meaning, ODE return, solver invocation and parameters visible; no numerical output or worked answer key.',686:'Both speed and acceleration curves with readable axes, units and temporal behavior visible.',687:'Gear conversion input program complete; no evaluated numeric outputs.',688:'Parameter declarations and full gear-sweep code including separate solve and speed conversion visible; no plotted or tabular results.',689:'Parameter declarations and both complete I_eff_arr and b_eff_arr expressions are visible after bottom-edge repair; no evaluated arrays or solution key.'}
checks={};out=[];held=[]
for old in [r for r in current['records'] if r['questionId'] in {'W05-L21-Q054','W05-L22-Q044','W05-L22-Q053'}]:
 qid=old['questionId']
 if False: continue
 r=records[qid]
 assert r==old,(qid,'changed record needs reinspection')
 for aid in r['assetIds']:
  if aid in checks:continue
  a=assets[aid];assert a['sourceSha256']==sourcehash
  p=R/a['path'];assert hashlib.sha256(p.read_bytes()).hexdigest()==a['sha256']
  pix=doc[a['physicalPage']-1].get_pixmap(matrix=fitz.Matrix(a['renderDpi']/72,a['renderDpi']/72),clip=fitz.Rect(a['cropRectangle']),alpha=False)
  im=Image.open(p).convert('RGB');assert im.size==(pix.width,pix.height)==(a['width'],a['height']);assert im.tobytes()==pix.samples,(qid,'pixel mismatch')
  checks[aid]={'assetSha256':a['sha256'],'assetMetadataSha256':sha(a),'originalPdfSha256':sourcehash,'physicalPage':a['physicalPage'],'rasterMatchesIndependentPdfRender':True,'visualInspection':notes[a['physicalPage']]}
 q=by[qid];assert question_hash(q)==r['questionSha256'];h=sha(r)
 out.append({'id':f'QVR-{qid}-lead-crop-{h[:12]}','visualId':r['id'],'visualVersion':r['version'],'visualSha256':h,'reviewerId':'independent-input-reviewer-integration-L20-L35','decision':'verified','questionId':qid,'questionVersion':q['version'],'questionSha256':question_hash(q),'sourceVersions':{s['sourceId']:s['sourceSha256'] for s in r['sourceRefs']},'assetHashes':{aid:assets[aid]['sha256'] for aid in r['assetIds']},'assetMetadataHashes':{aid:sha(assets[aid]) for aid in r['assetIds']},'reviewedAssetIds':r['assetIds'],'displayRole':'question_input','checks':dict.fromkeys(['inventoryCompleteness','requiredInputFidelity','legibility','noAnswerLeak','sourceLinkage'],True),'reviewedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reasoning':' '.join(dict.fromkeys(notes[assets[aid]['physicalPage']] for aid in r['assetIds'])),'scope':'Full current question stem, choices and assumptions independently read; every actual PNG independently visually inspected at readable scale. Raster pixels independently rerendered from hash-verified source PDF and matched exactly. This approves the pre-answer input role only, not browser display or a new answer judgment. Input labels/formulas/code are legitimate premises; worked numeric outputs and answer keys are excluded.','evidencePath':'audits/question-visual-review/lead/L20-L22-pixel-inspection-repaired.json','findings':[]})
p=R/'data/question-visuals/reviews/L20-L22-required-lead-repaired.json';assert not p.exists();p.write_text(json.dumps(out,indent=2)+'\n')
(R/'audits/question-visual-review/lead/L20-L22-pixel-inspection-repaired.json').write_text(json.dumps({'sourceSha256':sourcehash,'assets':checks,'approvedQuestionIds':[r['questionId'] for r in out],'held':held},indent=2)+'\n')
print(json.dumps({'approvedRequiredRecords':len(out),'independentlyComparedAssets':len(checks),'held':held}))
